use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl ExpressionVisitor { fn new (file_path : String) -> Self { Self { expressions : HashMap :: new () , current_file : file_path , } } fn normalize_expr (& self , expr : & Expr) -> String { match expr { Expr :: Binary (binary) => { format ! ("({} {} {})" , self . normalize_expr (& binary . left) , quote :: quote ! (# binary . op) . to_string () , self . normalize_expr (& binary . right)) } , Expr :: Call (call) => { let args : Vec < String > = call . args . iter () . map (| arg | self . normalize_expr (arg)) . collect () ; format ! ("call({})" , args . join (",")) } , Expr :: MethodCall (method) => { let args : Vec < String > = method . args . iter () . map (| arg | self . normalize_expr (arg)) . collect () ; format ! ("{}.{}({})" , self . normalize_expr (& method . receiver) , method . method , args . join (",")) } , Expr :: Field (field) => { format ! ("{}.{}" , self . normalize_expr (& field . base) , field . member . to_token_stream () . to_string ()) } , Expr :: Path (path) => { path . path . segments . iter () . map (| seg | seg . ident . to_string ()) . collect :: < Vec < _ > > () . join ("::") } , Expr :: Lit (lit) => format ! ("lit({})" , quote :: quote ! (# lit) . to_string ()) , _ => "expr" . to_string () , } } }